create function public.create_my_corporate_policy_request(p_corporate_account_id uuid,p_title text,p_service_type public.booking_service_type,p_route_or_destination text default null,p_travel_start date default null,p_travel_end date default null,p_customer_notes text default null,p_requested_budget numeric default null,p_requested_cabin text default null,p_requested_hotel_stars integer default null,p_lpo_ready boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_contact uuid;v_booking uuid;v_reference text;v_policy public.corporate_travel_policies%rowtype;v_exceptions text[]:='{}';v_task uuid;v_cabin text:=lower(nullif(btrim(coalesce(p_requested_cabin,'')),''));v_policy_snapshot jsonb:='{}';
begin
 if v_actor is null then raise exception 'Authentication required';end if;
 select corporate_contact_id into v_contact from public.corporate_portal_members where user_id=v_actor and corporate_account_id=p_corporate_account_id and status='active' and can_request=true;if not found then raise exception 'Corporate request access denied';end if;
 if char_length(btrim(coalesce(p_title,''))) not between 3 and 220 then raise exception 'Request title must be 3 to 220 characters';end if;
 if p_travel_start is not null and p_travel_end is not null and p_travel_end<p_travel_start then raise exception 'Travel end cannot be before travel start';end if;
 if p_requested_budget is not null and p_requested_budget<0 then raise exception 'Requested budget cannot be negative';end if;
 if v_cabin is not null and v_cabin not in('economy','premium_economy','business','first')then raise exception 'Invalid requested cabin';end if;
 if p_requested_hotel_stars is not null and p_requested_hotel_stars not between 1 and 5 then raise exception 'Requested hotel stars must be 1 to 5';end if;
 select * into v_policy from public.corporate_travel_policies where corporate_account_id=p_corporate_account_id and branch_id is null and status='active' and current_date>=effective_from and(effective_to is null or current_date<=effective_to)order by effective_from desc limit 1;
 if found then
  if v_policy.trip_budget_limit is not null and p_requested_budget is not null and p_requested_budget>v_policy.trip_budget_limit then v_exceptions:=array_append(v_exceptions,'budget_above_limit');end if;
  if p_travel_start is not null and p_travel_start<current_date+v_policy.advance_booking_days then v_exceptions:=array_append(v_exceptions,'advance_booking_shortfall');end if;
  if v_cabin is not null and array_position(array['economy','premium_economy','business','first'],v_cabin)>array_position(array['economy','premium_economy','business','first'],v_policy.max_cabin)then v_exceptions:=array_append(v_exceptions,'cabin_above_policy');end if;
  if v_policy.max_hotel_stars is not null and p_requested_hotel_stars is not null and p_requested_hotel_stars>v_policy.max_hotel_stars then v_exceptions:=array_append(v_exceptions,'hotel_stars_above_policy');end if;
  if v_policy.requires_lpo and not coalesce(p_lpo_ready,false)then v_exceptions:=array_append(v_exceptions,'lpo_required');end if;
  v_policy_snapshot:=jsonb_build_object('policy_id',v_policy.id,'policy_name',v_policy.policy_name,'currency',v_policy.currency,'trip_budget_limit',v_policy.trip_budget_limit,'advance_booking_days',v_policy.advance_booking_days,'max_cabin',v_policy.max_cabin,'max_hotel_stars',v_policy.max_hotel_stars,'requires_lpo',v_policy.requires_lpo,'evaluated_at',now());
 end if;
 v_reference:=public.next_booking_reference();
 insert into public.bookings(user_id,booking_reference,service_type,title,booking_kind,corporate_account_id,corporate_contact_id,route_or_destination,travel_start,travel_end,customer_notes,source,status,payment_status,created_by,priority,service_payload)values(v_actor,v_reference,p_service_type,btrim(p_title),'corporate',p_corporate_account_id,v_contact,nullif(btrim(coalesce(p_route_or_destination,'')),''),p_travel_start,p_travel_end,nullif(btrim(coalesce(p_customer_notes,'')),''),'corporate_portal','enquiry','not_requested',v_actor,case when cardinality(v_exceptions)>0 then'high' else'normal' end,jsonb_build_object('requested_budget',p_requested_budget,'requested_cabin',v_cabin,'requested_hotel_stars',p_requested_hotel_stars,'lpo_ready',coalesce(p_lpo_ready,false),'policy_evaluation',jsonb_build_object('policy',v_policy_snapshot,'exceptions',to_jsonb(v_exceptions),'exception_count',cardinality(v_exceptions))))returning id into v_booking;
 if cardinality(v_exceptions)>0 then insert into public.tasks_reminders(title,task_type,entity_type,entity_id,due_at,priority,notes,created_by,automation_key)values('Corporate policy review: '||left(btrim(p_title),150),'corporate_approval','booking',v_booking,now()+interval '2 hours','high','Review policy exceptions: '||array_to_string(v_exceptions,', '),v_actor,'corporate-policy-review:'||v_booking)returning id into v_task;end if;
 insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'corporate_portal.request_policy_evaluated','booking',v_booking,jsonb_build_object('reference',v_reference,'corporate_account_id',p_corporate_account_id,'policy_id',v_policy.id,'exceptions',to_jsonb(v_exceptions),'task_id',v_task));
 return jsonb_build_object('booking_id',v_booking,'reference',v_reference,'policy_name',v_policy.policy_name,'exceptions',to_jsonb(v_exceptions),'exception_count',cardinality(v_exceptions),'review_required',cardinality(v_exceptions)>0);
end$$;
revoke execute on function public.create_my_corporate_policy_request(uuid,text,public.booking_service_type,text,date,date,text,numeric,text,integer,boolean) from public,anon;
grant execute on function public.create_my_corporate_policy_request(uuid,text,public.booking_service_type,text,date,date,text,numeric,text,integer,boolean) to authenticated;
